"use client";
import type { ButtonHTMLAttributes } from "react";

// 全局按钮原语。主按钮裁决（2026-07-15）：提交/发送类动作统一 primary =
// accent 填充（旧黑底按钮身份废除）——accent 已是焦点/流式/选中的既定
// 强调身份，且随主题换肤。
//
// variant:
//   primary   — accent 实色填充（发送/提交/确认）
//   secondary — 描边 + surface（次要动作）
//   ghost     — 无边框纯文字（取消/低调动作）
//   danger    — danger 实色填充（删除等破坏性确认）
// size: sm = 行内小按钮；md = 表单/底栏默认

type Variant = "primary" | "secondary" | "ghost" | "danger";
type Size = "sm" | "md";

const VARIANT: Record<Variant, string> = {
  primary:
    "bg-accent hover:bg-accent-strong text-ink-inverse font-medium",
  secondary:
    "border border-line-strong bg-surface text-ink-muted hover:text-ink-strong hover:bg-surface-muted",
  ghost: "text-ink-muted hover:text-ink-strong hover:bg-surface-muted",
  danger: "bg-danger hover:bg-danger-strong text-ink-inverse font-medium",
};

const SIZE: Record<Size, string> = {
  sm: "px-2.5 py-1 text-ui rounded-md",
  md: "px-4 py-1.5 text-sm rounded-field",
};

export function Button({
  variant = "secondary",
  size = "md",
  loading = false,
  className = "",
  disabled,
  children,
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: Variant;
  size?: Size;
  loading?: boolean;
}) {
  return (
    <button
      disabled={disabled || loading}
      className={`inline-flex items-center justify-center gap-1.5 max-md:min-h-11 max-md:min-w-11 transition-colors active:scale-[0.98] disabled:opacity-40 disabled:cursor-not-allowed disabled:active:scale-100 ${VARIANT[variant]} ${SIZE[size]} ${className}`}
      {...rest}
    >
      {loading && (
        <span className="trellis-dots" aria-hidden>
          <span />
          <span />
          <span />
        </span>
      )}
      {children}
    </button>
  );
}

"use client";
import type { HTMLAttributes } from "react";

// 小徽标/pill 原语：模式徽章、未读计数、状态角标的统一外壳。
// tone 对应语义 hue；solid=实色填充（默认淡色 tint + 描边）。

type Tone =
  | "neutral"
  | "accent"
  | "warn"
  | "danger"
  | "positive"
  | "unread"
  | "fork";

const TINT: Record<Tone, string> = {
  neutral: "bg-surface-muted text-ink-muted border-line",
  accent: "bg-accent-muted text-accent-ink border-accent-line",
  warn: "bg-warn-muted text-warn-ink border-warn-line",
  danger: "bg-danger-muted text-danger-ink border-danger-line",
  positive: "bg-positive-muted text-positive-ink border-positive-line",
  unread: "bg-unread-muted text-unread-ink border-unread-line",
  fork: "bg-fork-muted text-fork-ink border-fork-line",
};

const SOLID: Record<Tone, string> = {
  neutral: "bg-ink-muted text-ink-inverse border-transparent",
  accent: "bg-accent text-ink-inverse border-transparent",
  warn: "bg-warn text-ink-inverse border-transparent",
  danger: "bg-danger text-ink-inverse border-transparent",
  positive: "bg-positive text-ink-inverse border-transparent",
  unread: "bg-unread text-ink-inverse border-transparent",
  fork: "bg-fork text-ink-inverse border-transparent",
};

export function Pill({
  tone = "neutral",
  solid = false,
  className = "",
  children,
  ...rest
}: HTMLAttributes<HTMLSpanElement> & { tone?: Tone; solid?: boolean }) {
  return (
    <span
      className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded border text-nano font-medium ${
        solid ? SOLID[tone] : TINT[tone]
      } ${className}`}
      {...rest}
    >
      {children}
    </span>
  );
}

