// 守卫：components / app / lib / hooks 里的颜色 utility 必须指向本项目注册过的颜色。
//
// 背景（S172）：写 `border-border` / `text-muted` 这类 shadcn 味的类名，Tailwind v4
// 不会报错、只是静默不生成 CSS——边框回落 currentColor 变黑框、文字不变灰。
// 本项目的颜色全部在 app/globals.css 的 @theme inline 里注册（line* / ink* /
// surface* / accent* …），还把 stone / indigo / amber / rose / emerald / fuchsia
// 六套默认调色板 reset 成 initial。这条测试把「类名 → 注册表」的对照做成静态扫描。
import { describe, expect, test } from "bun:test";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const ROOT = join(import.meta.dir, "..");
const SCAN_DIRS = ["app", "components", "lib", "hooks"];
const PALETTE = [
  "red", "orange", "amber", "yellow", "lime", "green", "emerald", "teal", "cyan", "sky", "blue",
  "indigo", "violet", "purple", "fuchsia", "pink", "rose", "slate", "gray", "zinc", "neutral", "stone",
];
const SPECIAL = new Set(["white", "black", "transparent", "current", "inherit"]);
const TEXT_SIZE_DEFAULT = new Set(["xs", "sm", "base", "lg", "xl", "2xl", "3xl", "4xl", "5xl", "6xl", "7xl", "8xl", "9xl"]);
const TEXT_MISC = /^(left|center|right|justify|start|end|wrap|nowrap|balance|pretty|ellipsis|clip)$/;
const BG_MISC = /^(none|cover|contain|auto|fixed|local|scroll|center|top|bottom|left|right|top-left|top-right|bottom-left|bottom-right|repeat|no-repeat|repeat-[xy]|repeat-round|repeat-space|clip-.*|origin-.*|gradient-to-.*|linear-.*|radial-.*|conic-.*|size-.*|position-.*|blend-.*)$/;
const BORDER_MISC = /^(\d+|box|solid|dashed|dotted|double|hidden|none|collapse|separate|spacing-.*)$/;
const BORDER_SIDE = /^([tblrxyse])(?:-(.+))?$/;
const DIVIDE_MISC = /^([xy](?:-(?:\d+|reverse))?|solid|dashed|dotted|double|hidden|none)$/;

export type Theme = { colors: Set<string>; resets: Set<string>; text: Set<string> };

export function readTheme(css: string): Theme {
  const start = css.indexOf("@theme inline");
  if (start < 0) throw new Error("app/globals.css: @theme inline block not found");
  const theme = css.slice(start);
  const colors = new Set<string>(), resets = new Set<string>(), text = new Set<string>();
  for (const m of theme.matchAll(/--color-([a-z0-9-]+?)(-\*)?\s*:\s*([^;]+);/g)) {
    if (m[2]) resets.add(m[1]);
    else if (m[3].trim() !== "initial") colors.add(m[1]);
  }
  for (const m of theme.matchAll(/--text-([a-z0-9]+)\s*:/g)) text.add(m[1]);
  return { colors, resets, text };
}

function isColor(token: string, theme: Theme) {
  if (SPECIAL.has(token) || theme.colors.has(token)) return true;
  const m = token.match(/^([a-z]+)-(50|[1-9]00|950)$/);
  return !!m && PALETTE.includes(m[1]) && !theme.resets.has(m[1]);
}

/** 返回 null = 合法（颜色已注册，或根本不是颜色类）；否则返回问题描述。 */
export function classify(prefix: string, rawToken: string, theme: Theme): string | null {
  const token = rawToken.replace(/\/\d+$/, "");
  if (token.startsWith("[") || token.endsWith("-")) return null;
  const need = (color: string) => isColor(color, theme) ? null
    : theme.resets.has(color.replace(/-(50|[1-9]00|950)$/, "")) ? `${prefix}-${rawToken}：调色板已在 @theme 里 reset`
    : `${prefix}-${rawToken}：颜色「${color}」未在 app/globals.css @theme 注册`;
  switch (prefix) {
    case "text":
      if (theme.text.has(token) || TEXT_SIZE_DEFAULT.has(token) || TEXT_MISC.test(token)) return null;
      return need(token);
    case "bg":
      if (BG_MISC.test(token)) return null;
      return need(token);

@import "tailwindcss";
@import "@xyflow/react/dist/style.css";
@import "highlight.js/styles/github-dark.css" layer(hljs);
@import "katex/dist/katex.min.css" layer(katex);

/* Tailwind v4: enable class-based dark variant.
   <html class="dark"> activates `dark:` utilities. ThemeScript in
   layout.tsx sets it before paint to avoid FOUC. */
@custom-variant dark (&:where(.dark, .dark *));

/* 参考稿的窄屏断点是「≤560px」，**含** 560。Tailwind 的 max-[560px] 编出来
   是 `width < 560px`，正好把 560 这一点漏在宽屏那侧（559 收窄、560 却还是宽
   版）。自定义一个包含边界的 variant，别用 max-[560.5px] 这种把意图藏进小数
   里的写法。用法：narrow:hidden / narrow:w-full。 */
@custom-variant narrow (@media (width <= 560px));

/* Highlight.js：只装 dark 一套 —— 「代码块恒暗」是设计决策（原来的
   light 层因 layer 顺序恒被 dark 覆盖，本就是死代码，已删）。
   要让某个主题用浅色代码块，覆盖 --code-* 变量并手写 ~20 行 hljs
   token 色映射即可，不走双 stylesheet 条件加载。 */

/* ───────────────────────── Design tokens ─────────────────────────
   双层结构：
   1) 原始变量（--surface 等）定义在普通 CSS 块里，参与级联——
      `.dark` 与 `[data-theme=X]` 通过覆盖这些变量实现暗色与多主题，
      组件端不再写 dark: 双份颜色。
   2) 下方 @theme inline 把它们注册成 Tailwind utility（bg-surface、
      text-ink-muted…）。`inline` 让 utility 直接引用 var()，在使用处
      解析、随主题级联；没有 inline 只会取 :root 静态值。
   默认主题的值精确取自 Tailwind v4 调色板（oklch 原值），保证
   token 化前后零视觉 diff。语义角色后缀约定：
     X        实色（按钮底/dot/实心 badge）
     X-strong 实色的 hover/加重档
     X-ink    淡色底上的文字
     X-muted  淡色填充底
     X-line   边框 / ring（mode 系另有 -line-strong 供激活态）        */

:root {
  color-scheme: light;

  /* Standalone viewport insets: env() lives here; components consume vars. */
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --trellis-header-h: calc(3rem + var(--safe-top));

  /* 中性族 —— stone */
  --surface-canvas: oklch(98.5% 0.001 106.423); /* stone-50 */
  --surface: #fff;
  --surface-raised: #fff;
  --surface-muted: oklch(97% 0.001 106.424); /* stone-100 */
  --scrim: oklch(14.7% 0.004 49.25); /* stone-950，配 /50 使用 */
  --line: oklch(92.3% 0.003 48.717); /* stone-200 */
  --line-strong: oklch(86.9% 0.005 56.366); /* stone-300 */
  --line-faint: oklch(97% 0.001 106.424); /* stone-100 */
  --ink: oklch(21.6% 0.006 56.043); /* stone-900 */
  --ink-strong: oklch(21.6% 0.006 56.043); /* stone-900 */
  --ink-muted: oklch(44.4% 0.011 73.639); /* stone-600 */
  --ink-faint: oklch(70.9% 0.01 56.259); /* stone-400 */
  --ink-inverse: #fff;

  /* accent —— indigo（主按钮/焦点/流式/选中） */
  --accent: oklch(51.1% 0.262 276.966); /* indigo-600 */
  --accent-strong: oklch(45.7% 0.24 277.023); /* indigo-700 */
  --accent-ink: oklch(35.9% 0.144 278.697); /* indigo-900 */
  --accent-muted: oklch(96.2% 0.018 272.314); /* indigo-50 */
  --accent-line: oklch(87% 0.065 274.039); /* indigo-200 */

  /* 状态色 —— warn(amber) / danger(rose) / positive(emerald) / unread(=emerald) */
  --warn: oklch(76.9% 0.188 70.08); /* amber-500 */
  --warn-ink: oklch(41.4% 0.112 45.904); /* amber-900 */
  --warn-muted: oklch(98.7% 0.022 95.277); /* amber-50 */
  --warn-line: oklch(87.9% 0.169 91.605); /* amber-300 */
  --danger: oklch(58.6% 0.253 17.585); /* rose-600 */
  --danger-strong: oklch(51.4% 0.222 16.935); /* rose-700 */
  --danger-ink: oklch(41% 0.159 10.272); /* rose-900 */
  --danger-muted: oklch(96.9% 0.015 12.422); /* rose-50 */
  --danger-line: oklch(89.2% 0.058 10.001); /* rose-200 */
  --positive: oklch(69.6% 0.17 162.48); /* emerald-500 */
  --positive-ink: oklch(37.8% 0.077 168.94); /* emerald-900 */
  --positive-muted: oklch(97.9% 0.021 166.113); /* emerald-50 */
  --positive-line: oklch(84.5% 0.143 164.978); /* emerald-300 */
  --unread: oklch(69.6% 0.17 162.48); /* emerald-500 */
  --unread-ink: oklch(37.8% 0.077 168.94); /* emerald-900 */
  --unread-muted: oklch(97.9% 0.021 166.113); /* emerald-50 */
  --unread-line: oklch(84.5% 0.143 164.978); /* emerald-300 */

  /* fork —— 分叉锚点（banner/badge），默认与 warn 同值但独立可换 */
  --fork: oklch(76.9% 0.188 70.08); /* amber-500 */
  --fork-ink: oklch(41.4% 0.112 45.904); /* amber-900 */
  --fork-muted: oklch(98.7% 0.022 95.277); /* amber-50 */
  --fork-line: oklch(87.9% 0.169 91.605); /* amber-300 */

  /* mode 双色 —— 与状态色解耦（值同 stone/rose 但独立变量） */
  --mode-chat: oklch(70.9% 0.01 56.259); /* stone-400 */
  --mode-chat-ink: oklch(37.4% 0.01 67.558); /* stone-700 */
  --mode-chat-muted: oklch(97% 0.001 106.424); /* stone-100 */
  --mode-chat-line: oklch(86.9% 0.005 56.366); /* stone-300 */
  --mode-chat-line-strong: oklch(70.9% 0.01 56.259); /* stone-400 */

